class Solution{public:vector<double>calcEquation(vector<vector<string>>&e,vector<double>&v,vector<vector<string>>&q){unordered_map<string,vector<pair<string,double>>>g;for(int i=0;i<e.size();i++){g[e[i][0]].push_back({e[i][1],v[i]});g[e[i][1]].push_back({e[i][0],1/v[i]});}vector<double>r;for(auto&z:q){unordered_set<string>s;function<double(string,string)>f=[&](string u,string t){if(!g.count(u))return -1.0;if(u==t)return 1.0;s.insert(u);for(auto [x,w]:g[u])if(!s.count(x)){double k=f(x,t);if(k>=0)return w*k;}return -1.0;};r.push_back(f(z[0],z[1]));}return r;}};
